    float* data = img->data;
    float invh = 1.0f / (width > height ? width : height);
    float invw = 1.0f / (width > height ? width : height);
    float freqs[] = {2.0, 4.0, 16.0};
    float ampls[] = {0.2, 0.05, 0.01};
    int y;
#pragma omp parallel for
 for (y = 0; y < height; ++y) {
        float v = y * invh;
        float* dst = data + y * width;
        for (int x = 0; x < width; ++x) {
            float u = x * invw;
            *dst++ = ampls[0] * open_simplex_noise2(ctx, u * freqs[0], v * freqs[0]) + ampls[1] * open_simplex_noise2(ctx, u * freqs[1], v * freqs[1]) + ampls[2] * open_simplex_noise2(ctx, u * freqs[2], v * freqs[2]);
        }
